const { email, organizationId } = trigger.data;
const res = await fetch(process.env.MANTLE_API_URL, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${process.env.MANTLE_SERVICE_TOKEN}`
  },
  body: JSON.stringify({
    query: `query FindPerson($orgId: String!) {
      people(condition: { organizationId: $orgId }, filter: { emails: { contains: ["${email}"] } }) {
        nodes {
          rowId
          firstName
        }
      }
    }`,
    variables: { orgId: organizationId }
  })
});
const json = await res.json();
const nodes = json.data?.people?.nodes ?? [];
return { person: nodes[0] ?? null, email, organizationId };

const { person } = steps['query-mantle'].output;
const { userId } = trigger.data;
const res = await fetch(process.env.MANTLE_API_URL, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${process.env.MANTLE_SERVICE_TOKEN}`
  },
  body: JSON.stringify({
    query: `mutation CreatePersonExternalLink($input: CreatePersonExternalLinkInput!) {
      createPersonExternalLink(input: $input) {
        personExternalLink {
          rowId
          provider
          externalId
        }
      }
    }`,
    variables: {
      input: {
        personExternalLink: {
          personId: person.rowId,
          provider: 'gatekeeper',
          externalId: userId
        }
      }
    }
  })
});
const json = await res.json();
return { linked: json.data?.createPersonExternalLink?.personExternalLink ?? null };

const { email, organizationId } = steps['query-mantle'].output;
const { userId } = trigger.data;
const firstName = email.split('@')[0];
const headers = {
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${process.env.MANTLE_SERVICE_TOKEN}`
};
const createRes = await fetch(process.env.MANTLE_API_URL, {
  method: 'POST',
  headers,
  body: JSON.stringify({
    query: `mutation CreatePerson($input: CreatePersonInput!) {
      createPerson(input: $input) {
        person {
          rowId
        }
      }
    }`,
    variables: {
      input: {
        person: {
          firstName,
          lastName: '',
          emails: [email],
          organizationId
        }
      }
    }
  })
});
const createJson = await createRes.json();
const personId = createJson.data?.createPerson?.person?.rowId;
if (!personId) throw new Error('Failed to create person');
const linkRes = await fetch(process.env.MANTLE_API_URL, {
  method: 'POST',
  headers,
  body: JSON.stringify({
    query: `mutation CreatePersonExternalLink($input: CreatePersonExternalLinkInput!) {
      createPersonExternalLink(input: $input) {
        personExternalLink {
          rowId
          provider
          externalId
        }
      }
    }`,
    variables: {
      input: {
        personExternalLink: {
          personId,
          provider: 'gatekeeper',
          externalId: userId
        }
      }
    }
  })
});
const linkJson = await linkRes.json();
return { person: { rowId: personId }, linked: linkJson.data?.createPersonExternalLink?.personExternalLink ?? null };
